import { type CSSProperties, useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

export interface AnimatedCountProps {
  value: number;
  fontSize?: number;
  /** 数字之间的字距（px） */
  gap?: number;
  /** 左右内边距（px） */
  horizontalPadding?: number;
  textColor?: string;
  fontWeight?: number | string;
  className?: string;
  style?: CSSProperties;
}

const DURATION_MS = 520;

function easeOutCubic(progress: number) {
  return 1 - (1 - progress) ** 3;
}

/**
 * 数值滚动：value 变化时从当前显示值平滑过渡到新值。
 * 使用等宽数字，避免过渡过程中宽度跳动。
 */
export function AnimatedCount({
  value,
  fontSize,
  gap = 0,
  horizontalPadding = 0,
  textColor,
  fontWeight,
  className,
  style,
}: AnimatedCountProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const displayRef = useRef(value);
  const frameRef = useRef<number | null>(null);
  const [display, setDisplay] = useState(value);

  useEffect(() => {
    if (prefersReducedMotion) {
      displayRef.current = value;
      setDisplay(value);
      return undefined;
    }

    const from = displayRef.current;
    const delta = value - from;
    if (delta === 0) return undefined;

    const startedAt = performance.now();
    const step = (now: number) => {
      const progress = Math.min((now - startedAt) / DURATION_MS, 1);
      const next = from + delta * easeOutCubic(progress);
      displayRef.current = next;
      setDisplay(next);
      frameRef.current = progress < 1 ? requestAnimationFrame(step) : null;
    };

    frameRef.current = requestAnimationFrame(step);
    return () => {
      if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
      frameRef.current = null;
    };
  }, [prefersReducedMotion, value]);

  return (
    <span
      className={className}
      style={{
        ...style,
        display: "inline-block",
        fontSize,
        fontWeight,
        color: textColor,
        letterSpacing: gap ? `${gap}px` : undefined,
        paddingInline: horizontalPadding || undefined,
        fontVariantNumeric: "tabular-nums",
      }}
    >
      {Math.round(display)}
    </span>
  );
}

export default AnimatedCount;
