import {
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

export interface ContentRevealProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  children?: ReactNode;
  /** 揭示时是否附带一层模糊消散 */
  blur?: boolean;
  /** 揭示时长（毫秒） */
  duration?: number;
  /** 进入视口后的等待时间（毫秒） */
  delay?: number;
  /** 可见比例达到该值时开始揭示；0 表示刚露出即触发 */
  threshold?: number;
  /** 揭示完成时回调 */
  onReveal?: () => void;
  className?: string;
  style?: CSSProperties;
}

const DEFAULT_DURATION = 600;
const DEFAULT_THRESHOLD = 0.1;
const BLUR_START_PX = 12;

/**
 * 滚动入场容器：内容进入视口后由透明（可选模糊）过渡到完全可见。
 * 用户开启「减少动态效果」时直接呈现最终状态，不播放过渡。
 */
export function ContentReveal({
  children,
  blur = false,
  duration = DEFAULT_DURATION,
  delay = 0,
  threshold = DEFAULT_THRESHOLD,
  onReveal,
  className,
  style,
  ...rest
}: ContentRevealProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const revealCallbackRef = useRef(onReveal);
  const prefersReducedMotion = usePrefersReducedMotion();
  const [revealed, setRevealed] = useState(false);

  revealCallbackRef.current = onReveal;

  useEffect(() => {
    if (revealed) return undefined;
    const host = hostRef.current;
    if (!host) return undefined;

    if (prefersReducedMotion || typeof IntersectionObserver === "undefined") {
      setRevealed(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (!entries.some((entry) => entry.isIntersecting)) return;
        setRevealed(true);
        observer.disconnect();
      },
      { threshold: Math.min(Math.max(threshold, 0), 1) },
    );
    observer.observe(host);
    return () => observer.disconnect();
  }, [prefersReducedMotion, revealed, threshold]);

  useEffect(() => {
    if (revealed) revealCallbackRef.current?.();
  }, [revealed]);

  const settled = revealed || prefersReducedMotion;
  const transition = prefersReducedMotion
    ? "none"
    : `opacity ${duration}ms ease-out ${delay}ms, filter ${duration}ms ease-out ${delay}ms`;

  return (
    <div
      {...rest}
      ref={hostRef}
      className={className}
      style={{
        ...style,
        opacity: settled ? 1 : 0,
        filter: blur && !settled ? `blur(${BLUR_START_PX}px)` : "none",
        transition,
      }}
    >
      {children}
    </div>
  );
}

export default ContentReveal;
